"""Immutable, independently-generated G1 admission cryptographic vectors."""
from __future__ import annotations

import base64
import hashlib
import zlib
from datetime import datetime, timezone

from src.signer_admission_grant import (
    AdmissionGrantContext,
    AdmissionIssuerKeyV1,
    GRANT_DOMAIN,
    GRANT_SCHEMA,
    GRANT_SIGNATURE_SCHEMA,
    REQUEST_BINDING_DOMAIN,
    admission_request_binding,
    parse_strict_signer_authorization_request,
    verify_admission_grant,
)


# Produced once by an independent RFC8785 implementation and deterministic
# test key.  These are literal frozen bytes, never generated by production.
VECTOR_SET = "PROPHET_SIGNER_ADMISSION_GRANT_CRYPTOGRAPHIC_VECTOR_SET_V1"
_RAW = ""
_BINDING_JCS = ""
_PREIMAGE = ""
_GRANT_JCS = ""
_GRANT_PREIMAGE = ""


def _frozen(value: str) -> bytes:
    return zlib.decompress(base64.b64decode(value))


def test_frozen_request_binding_vector_is_exact():
    request = parse_strict_signer_authorization_request(_frozen(_RAW))
    jcs, preimage, digest = admission_request_binding(request)
    assert jcs == _frozen(_BINDING_JCS)
    assert len(jcs) == 2695
    assert preimage == _frozen(_PREIMAGE)
    assert preimage == REQUEST_BINDING_DOMAIN + b"\x87\x0a\x00\x00" + jcs
    assert digest == "ddc58c91f42fe4b8bf143d512cfb59db7229e8893bb552aaa4a5327f89d4134a"


def test_frozen_signed_grant_vector_is_exact():
    request = parse_strict_signer_authorization_request(_frozen(_RAW))
    grant = {"schema": GRANT_SCHEMA, "version": 1, "grant_id": "c" * 32, "environment": "public-devnet", "git_sha": "a" * 40, "evidence_set_id": "evidence-001", "acceptance_run_id": "b" * 32, "signer_role": "A", "signer_service_id": "signer-a", "admission_request_sha256": "ddc58c91f42fe4b8bf143d512cfb59db7229e8893bb552aaa4a5327f89d4134a", "issuer_id": "issuer-a", "key_id": "key-a", "issued_at": "2026-08-27T11:30:00Z", "valid_until": "2026-08-27T12:30:00Z"}
    assert _frozen(_GRANT_JCS) == b'{"acceptance_run_id":"bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb","admission_request_sha256":"ddc58c91f42fe4b8bf143d512cfb59db7229e8893bb552aaa4a5327f89d4134a","environment":"public-devnet","evidence_set_id":"evidence-001","git_sha":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","grant_id":"cccccccccccccccccccccccccccccccc","issued_at":"2026-08-27T11:30:00Z","issuer_id":"issuer-a","key_id":"key-a","schema":"PROPHET_SIGNER_ADMISSION_GRANT_V1","signer_role":"A","signer_service_id":"signer-a","valid_until":"2026-08-27T12:30:00Z","version":1}'
    preimage = _frozen(_GRANT_PREIMAGE)
    assert preimage == GRANT_DOMAIN + b"\x12\x02\x00\x00" + _frozen(_GRANT_JCS)
    assert hashlib.sha256(preimage).hexdigest() == "a2e34be0f9af3481a24d1b6de99861b877b1fa5405007823070be8dc686c39c3"
    envelope = {"schema": GRANT_SIGNATURE_SCHEMA, "version": 1, "algorithm": "ed25519", "issuer_id": "issuer-a", "key_id": "key-a", "signed_payload_sha256": "a2e34be0f9af3481a24d1b6de99861b877b1fa5405007823070be8dc686c39c3", "signature": "c9087242c65ba3b0f4bb3f8724082cbb8d0046f05c7181ec71d665ee38b760e7c4f90dbf5e285d1dba4723b76ae0807601b5d00bda9b6a989eafc426b12ab201"}
    context = AdmissionGrantContext("A", "signer-a", "public-devnet", "a" * 40, "evidence-001", "b" * 32)
    key = AdmissionIssuerKeyV1("key-a", "issuer-a", "A", "FAe4sisG95oZ42w7buUn5qEE4TAnfTTFPiguZUHmhiF", "2026-08-27T11:00:00Z", "2026-08-27T13:00:00Z")
    result = verify_admission_grant(unsigned_grant=grant, signature_envelope=envelope, request=request, context=context, issuer_keys=[key], trusted_now=datetime(2026, 8, 27, 12, 0, tzinfo=timezone.utc))
    assert result.grant_id == "c" * 32
